# Cascade router: cheap model first, escalate if the validator rejects
def small_model(q):
    return "42" if len(q) < 30 else "I am not sure"     # weak on long questions

def large_model(q):
    return "A detailed, correct answer"

def validator(ans):
    return "not sure" not in ans.lower()                 # simple confidence check

COST = {"small": 1, "large": 10}

def route(q):
    if "code" in q or "prove" in q:                      # hard signal: go straight up
        return "large", large_model(q), COST["large"]
    ans = small_model(q)
    if validator(ans):
        return "small", ans, COST["small"]
    return "large(escalated)", large_model(q), COST["small"] + COST["large"]

total = 0
for q in ["what is 6*7?", "explain the tradeoffs between two vector indexes please", "write code for a trie"]:
    tier, ans, cost = route(q)
    total += cost
    print("%-55s -> %s cost=%d" % (q, tier, cost))
print("total cost", total, "vs all-large", 3 * COST["large"])
